import{_ as e,o,c as t,a3 as p}from"./chunks/framework.D3kUw6rp.js";const i="/assets/0.IjTTZvvs.png",r="/assets/1.Ddgf-Pyw.png",d="/assets/2.Cm47PkOF.jpeg",s="/assets/3.Cdi4GECD.jpeg",l="/assets/128.DT9cL5_1.png",h="/assets/256.EozSbPXj.png",f=JSON.parse('{"title":"个人数据存储方案","description":"","frontmatter":{},"headers":[],"relativePath":"article/2025/digital-assets/index.md","filePath":"article/2025/digital-assets/index.md"}'),n={name:"article/2025/digital-assets/index.md"};function c(u,a,m,b,_,q){return o(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="个人数据存储方案" tabindex="-1">个人数据存储方案 <a class="header-anchor" href="#个人数据存储方案" aria-label="Permalink to &quot;个人数据存储方案&quot;">​</a></h1><p><img src="'+i+'" alt=""></p><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>在我们的工作与生活中会产生非常多的数字数据如: 文档，照片，视频，各种项目工程文件等。</p><p>得益于计算机的强大能力与硬盘的不断升级，我们现在可以轻松的储存并访问这些数据。</p><p>记得小时候稻谷收割回来，我们需要把稻谷晒干，用手摇吹风机将一些枯草枝叶等杂物分离出来，再将稻谷倒入谷仓封存起来。期间需要防备老鼠等生物的入侵，以满足接下来一年的粮食供应。</p><p>如果是生姜挖回来，我们也会在后院的土墙中间挖一个坑洞，将生姜放进去保存，这样生姜可以吃很久。</p><p>商业化的今天，我们已经很少有这些<code>实物</code>需要储藏保管了。之前是每个个体都需要自建粮仓，自己防护。现在这些物品都由第三方统一管理，这样可以构建更规范，安全，利用率高的粮仓。作为个体，我们按需购买即可。</p><p>取而代之的是我们数字化生活的数字资产，我们只要维护好这些<code>资产</code>，就足以在社会安身立命。</p><p>对程序员来说可能是一份项目代码</p><p>对设计师来说可能是一些设计稿件</p><p>对音乐人来说可能是一些音频文件</p><p>无论如何，再也不用偌大的物理空间，只需一块小小的硬盘，甚至是一个云存储的账号，就可以保管这些数据。</p><p>不过依然需要经历 <code>分类</code>、<code>去杂</code>、<code>存储</code>、<code>防护</code>让我们的数据更安全合理的保管起来。</p><p>本篇文章我将阐述我是如何保管个人数字资产。<strong>没有高级牛逼的手段，都是一些触手可得的方案</strong></p><h2 id="断舍离" tabindex="-1">断舍离 <a class="header-anchor" href="#断舍离" aria-label="Permalink to &quot;断舍离&quot;">​</a></h2><p>在讨论如何管理数据之前，我更愿意讨论如何沉淀数据，把真正需要，有用的数据沉淀下来，才是高效存储的关键。</p><p><img src="'+r+'" alt=""></p><p>你们也许也见识过一些长辈，虽然房子很大，但是永远没有一个宽敞干净的地方落脚。空间里堆满杂物，问就是这些都有用，或者未来可能有用，不能丢。</p><p>而回到现代年轻人就是可能一个姿势的图片在相册中可能保留了 10 几张，问就是表情略有不同！或者这个也好看，那个也好看，不能删！</p><p>对我个人来说，不仅同一个姿势，甚至是同一个场景，我都不愿意保留略显重复的照片，我基本都会删除到只剩下一张。</p><p>所以我的数据管理哲学就是先学会「断舍离」，将不重要的数据果断的删除，从一堆庞杂的数据中择取一些精华进行保留。</p><h2 id="各种数据" tabindex="-1">各种数据 <a class="header-anchor" href="#各种数据" aria-label="Permalink to &quot;各种数据&quot;">​</a></h2><p>我的数字资产大致可以分为以下几种：</p><h3 id="文字信息" tabindex="-1">文字信息 <a class="header-anchor" href="#文字信息" aria-label="Permalink to &quot;文字信息&quot;">​</a></h3><p>是文字而非文章，也就是只是用文字记录的简短的信息。</p><p>比如家人的身份证号码、一些银行卡的开户行卡号、待办事项等。</p><p>这些数据我都用苹果自带的「备忘录」记录保存，因为它足够简单，而且通过 iCloud 可以在我的各个设备中无缝同步。</p><h3 id="文章数据" tabindex="-1">文章数据 <a class="header-anchor" href="#文章数据" aria-label="Permalink to &quot;文章数据&quot;">​</a></h3><p>平时我会在<code>掘金</code> 、 <code>少数派</code> 发布一些文章。根据平台的不同定位，发布的内容也有不同。最终统一收纳的地方就是我的个人博客站。第三方平台可以让我的文字被更多的人看到，而我的博客站能让我有踏实的数据掌控感。</p><h3 id="照片数据" tabindex="-1">照片数据 <a class="header-anchor" href="#照片数据" aria-label="Permalink to &quot;照片数据&quot;">​</a></h3><p>因为一直都是使用 iPhone 且未来也大概不会更换平台，所以照片就直接用 iCloud 来存储与同步。</p><h3 id="视频数据" tabindex="-1">视频数据 <a class="header-anchor" href="#视频数据" aria-label="Permalink to &quot;视频数据&quot;">​</a></h3><p>对于非视频创作者，其实我的照片和视频是属于同一数据类。</p><h3 id="代码数据" tabindex="-1">代码数据 <a class="header-anchor" href="#代码数据" aria-label="Permalink to &quot;代码数据&quot;">​</a></h3><p>我所有的代码都是托管在 Github ，包括我的个人博客也是托管在 Github 并且使用了免费的 GitPage 来发布。</p><h3 id="书签" tabindex="-1">书签 <a class="header-anchor" href="#书签" aria-label="Permalink to &quot;书签&quot;">​</a></h3><p>互联网从业者还有一个比较特殊的数据就是书签，这个就直接交给浏览器自带的同步功能来存储了，各个网站的密码也是，我都是交给谷歌浏览器。所以对于网上冲浪这件事，我只需要记得谷歌账号就行。</p><h3 id="文档类" tabindex="-1">文档类 <a class="header-anchor" href="#文档类" aria-label="Permalink to &quot;文档类&quot;">​</a></h3><p>一些重要证件的 PDF 扫描文件、个人简历、一些密钥等零散的小文件统一都放 iCloud 保存。</p><h3 id="自定义短语" tabindex="-1">自定义短语 <a class="header-anchor" href="#自定义短语" aria-label="Permalink to &quot;自定义短语&quot;">​</a></h3><p>对于需要频繁输入且准确性要求非常高的数据，我会将其录入到 「自定义短语」 中。</p><p>比如我的收货地址、身份证号码和手机号等。哪怕你都熟记在心，但是你不能保证每次都输入正确。</p><p>而将他们录入到「自定义短语」中就可以输入几个关键字就自动联想出来。结合 iCloud 的同步功能，我可以在所有苹果设备中享受这种便利。</p><h2 id="icloud" tabindex="-1">iCloud <a class="header-anchor" href="#icloud" aria-label="Permalink to &quot;iCloud&quot;">​</a></h2><p>由于电脑和手机都是使用苹果的产品，所以顺理成章的我的数据同步方案最优选就是 iCloud 。</p><p>iCloud 有个很好的功能叫「优化 iPhone 存储空间」，它可以让较小的图片资源存在于手机，不影响我们浏览，当我们聚焦到某个照片时，它会从 iCloud 拉取原图。</p><p>我对这个功能有个小的优化建议，就是最好可以「按需」进行优化，比如最近 3 个月的照片是原图在本地，超过 3 个月的才是缩略图在本地。</p><p>因为从使用情况来看，我们会频繁翻阅的都是近期的照片。这样就是体验和容量都达到了最优解。</p><p><img src="'+d+'" alt=""></p><p>这样极大的释放了设备的本地空间，导致我的 128 GB 的手机用了 4 年了，依然有宽裕的存储空间。</p><p><img src="'+s+'" alt=""></p><p>所以我一直不建议花大价钱买大容量的 iPhone，我开通的是 21 元每月的 iCloud 套餐。有 200GB 的共享空间，足够我存放数据了。</p><p><code>21 * 12 = 252</code> 元每年</p><p>按照 3 年一个换机周期来算，花在存储的钱是 756 元。 而这个 765 元得到是可共享的 200GB 的空间。 而在 iPhone 的定价规则里，你想增加 200GB 成本应该是大于 756 元的。</p><p><img src="'+l+'" alt=""></p><p>而且购买大容量的设备是一个不可逆的行为，比如你这次买的是 256GB 的手机，那么下次你只能买大于等于 256GB 的手机。</p><p><img src="'+h+'" alt=""></p><h2 id="关于安全性" tabindex="-1">关于安全性 <a class="header-anchor" href="#关于安全性" aria-label="Permalink to &quot;关于安全性&quot;">​</a></h2><p>将数据放云上是最安全的，且 iCloud 和 GitHub 都是世界级大公司背书，我没有理由多此一举的去质疑可靠性。</p><p>至于 NAS 玩家经常提的隐私性安全，我个人完全不担心，我的所有数据都是个人生活类，不涉及任何社会阴暗面的东西。</p><p>不怕所谓的审查也不担心泄漏。（何况我对苹果和微软有职业底线的信任感）</p><h2 id="结尾" tabindex="-1">结尾 <a class="header-anchor" href="#结尾" aria-label="Permalink to &quot;结尾&quot;">​</a></h2><p>以上就是本人对于数字资产管理的一点经验，没有复杂的操作成本，没有先进的高级概念，一切都是触手可及的。</p><p>数据整理本来就应该是一件简单又轻松的事情，我也很享受当下这种设备在手，只要有网，所有数据都触手可及的便捷性。</p>',65)])])}const x=e(n,[["render",c]]);export{f as __pageData,x as default};
